settings.custom_css:
selector{
    position: absolute;
}


.scroll-left,
.scroll-right,
.scroll-bottom,
.scroll-top {
    opacity: 0;
    filter: blur(10px); /* aqui o blur inicial */
    transition: 0.6s all ease;
}

/* Mantém seus transforms separados */
.scroll-left {
    transform: translate3d(-30px, 0, 0);
}

.scroll-right {
    transform: translate3d(30px, 0, 0);
}

.scroll-bottom {
    transform: translate3d(0, 80px, 0);
}

.scroll-top {
    transform: translate3d(0, -80px, 0);
}

/* Estado ativo */
.ativo {
    opacity: 1;
    filter: blur(0); /* remove o blur */
    transform: translate3d(0, 0, 0);
}

page_settings.custom_css:
::selection {
    background-color: rgba(255, 255, 255, 0.125);
}

html, body {
    overflow-x: hidden;
}

p:last-of-type {
    margin-bottom: 0;
}

body::-webkit-scrollbar {
    width: 10px; /* largura da barra de rolagem */
}

body::-webkit-scrollbar-track {
    background-color: #111111; /* cor da área de rastreamento */
}

body::-webkit-scrollbar-thumb {
    background: linear-gradient(90deg, #fff, #fff); /* cor do SCROLL*/
    border-radius: 15px; /* arredondamento do SCROLL */
    border: 2px solid #111111; /* cria espaçamento em torno do SCROLL*/
}

.botao{
    overflow: hidden !important;
    border-radius: 10px;
}

.botao .elementor-button{
    background: linear-gradient(
        -45deg,
        #FF6B35,
        #D94A18,
        #FF6B35,
        #FF8A5C,
        #FF6B35,
        #D94A18
    );
    background-size: 800% 400%;
    transition: all .3s;
    animation: gradient 2.5s infinite cubic-bezier(.62, .28, .23, .99) both;
}

@keyframes gradient {
    0%, 100% {
        background-position: 0% 50%;
    }

    50% {
        background-position: 100% 50%;
    }
}

.botao .elementor-button-text{
    align-self: center;
    padding-right: 0px;
    z-index: 9;
    transition: .3s ease;
}

.botao:hover .elementor-button-text{
    color: #FF6B35;
    transition: 1.3s ease;
}

.botao .elementor-button::before{
    content: "";
    background: white;
    width: 100%;
    height: 100%;
    position: absolute;
    top: 0;
    left: 0;
    border-radius: 10px;
    transform: scaleX(0);
    transform-origin: left;
    transition: .3s ease;
}

.botao:hover .elementor-button::before{
    transform: scaleX(1);
    transform-origin: left;
    transition: 1.3s ease;
}

.botao .elementor-button::after{
    content: '';
    background: linear-gradient(
        10deg,
        rgba(255,255,255,.75) 12.81%,
        rgba(255,255,255,0) 66.66%
    );

    mix-blend-mode: overlay;

    width: 90px;
    height: 160%;

    position: absolute;
    bottom: 0%;

    transform: translateX(-50%) skew(-25deg);

    user-select: none;
    pointer-events: none;

    animation: shinery 2s infinite ease-in-out;
}

@keyframes shinery {
    0% {
        left: -10%;
        opacity: 0;
    }

    10% {
        opacity: 1;
    }

    60% {
        left: 140%;
        opacity: 1;
    }

    65% {
        opacity: 0;
    }

    100% {
        left: 140%;
        opacity: 0;
    }
}
